def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 250:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    days_left = max(0, 10 - day)
    safe_budget = days_left * DAILY_SALARY * 0.42

    if hp <= 2 or no_water_days >= 2:
        bid = max(62.0, highest_prev + 4.0, avg_prev + 8.0)
        return float(min(budget, bid))

    if hp <= 4 or no_water_days >= 1:
        bid = max(46.0, highest_prev + 2.0, avg_prev + 4.0)
        if supply <= 17:
            bid += 8.0
        return float(min(budget, bid))

    base = 24.0 + 14.0 * scarcity

    if highest_prev >= 120:
        base = min(base, 34.0)
    elif highest_prev >= 85:
        base = max(base, 38.0)
    elif highest_prev > 0:
        base = max(base, min(52.0, highest_prev + 1.5))

    if urgent_opp >= 2:
        base += 6.0
    elif urgent_opp == 1:
        base += 3.0

    if rich_opp >= 2 and supply <= 18:
        base += 5.0

    if budget > safe_budget + 120:
        base += 4.0
    elif budget < safe_budget:
        base -= 6.0

    if day >= 8:
        base += 6.0

    if hp >= 8 and supply >= 22 and highest_prev >= 100:
        base = min(base, 22.0)

    bid = max(0.0, min(budget, base))
    return float(bid)

